SINA_SMART["anat1-surface-joints"] = {"lecture":"anat1-surface-joints","title":"Surface anatomy and joints of the upper limb","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-surface-joints:e0","text":"Five regions: shoulder, arm, elbow, forearm, hand.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-surface-joints:e1","text":"Deltopectoral groove disappears in shoulder dislocation.","topic":"Surface anatomy","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-surface-joints:e2","text":"Brachial pulse in the medial bicipital groove; 'M' veins for venepuncture.","topic":"Surface anatomy","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-surface-joints:e3","text":"Olecranon + epicondyles: triangle at 90° flexion, line in extension.","topic":"Surface anatomy","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-surface-joints:e4","text":"Radial pulse between FCR and brachioradialis tendons.","topic":"Surface anatomy","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-surface-joints:e5","text":"Snuffbox: EPL medial; EPB and APL lateral.","topic":"Surface anatomy","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-surface-joints:e6","text":"Shoulder: 3 degrees of freedom; lax capsule; anterior dislocations common.","topic":"Joints","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-surface-joints:e7","text":"Glenohumeral ligaments + coracohumeral ligament reinforce the front.","topic":"Joints","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-surface-joints:e8","text":"Elbow: humero-ulnar, humeroradial, proximal radio-ulnar; 1 degree (flexion-extension).","topic":"Joints","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-surface-joints:e9","text":"Wrist: radius + TFCC with scaphoid, lunate, triquetrum; 2 degrees.","topic":"Joints","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"3if4dy":"a","1oqvtfp":"a","j6bxbz":"a","xv00mj":"a","168n4j4":"a","1bh0twk":"a","19rv1e1":"a","txt7fh":"a","ivrpwd":"a","1yy22z4":"a","1mvuo4j":"a","e83cd9":"a","12e2fkg":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-surface-joints:e0":{"s":0,"u":["Five regions: shoulder, arm, elbow, forearm, hand.","The upper limb has five topographical regions: shoulder, arm, elbow, forearm and hand ."],"dp":[]},"anat1-surface-joints:e1":{"s":1,"u":["Deltopectoral groove disappears in shoulder dislocation.","The clavicle separates the supraclavicular fossa from the pectoral region, which is divided from the deltoid by the deltopectoral groove (this disappears in shoulder dislocation)."],"dp":[]},"anat1-surface-joints:e2":{"s":1,"u":["Brachial pulse in the medial bicipital groove; 'M' veins for venepuncture.","Elbow : in front, three projections (biceps in the middle, epicondylar muscle masses on each side) separated by the medial and lateral bicipital grooves ; the brachial pulse is felt in the medial groove, and the thin skin shows the 'M' venous network , the preferred site for injections and blood tests."],"dp":[{"h":"Note","t":"Cubital 'M' veins (cephalic, basilic, median cubital) are the usual site for venepuncture."}]},"anat1-surface-joints:e3":{"s":1,"u":["Olecranon + epicondyles: triangle at 90° flexion, line in extension.","Behind, the olecranon and the two epicondyles form an isosceles triangle with the elbow flexed at 90° and a straight line in extension ; this relationship is altered in elbow dislocation."],"dp":[{"h":"Clinical","t":"Elbow triangle : olecranon + two epicondyles form an isosceles triangle at 90° flexion and a straight line in extension. The relationship is lost in dislocation and kept in a supracondylar fracture ."}]},"anat1-surface-joints:e4":{"s":1,"u":["Radial pulse between FCR and brachioradialis tendons.","Wrist : in front, the tendons of flexor carpi ulnaris (medial), palmaris longus and flexor carpi radialis, and brachioradialis (lateral); the radial pulse is felt in the groove between FCR and brachioradialis ; behind, the ulnar head is prominent."],"dp":[{"h":"Note","t":"Pulses : brachial in the medial bicipital groove ; radial between the FCR and brachioradialis tendons."}]},"anat1-surface-joints:e5":{"s":1,"u":["Snuffbox: EPL medial; EPB and APL lateral."],"dp":[{"h":"Note","t":"Anatomical snuffbox : EPL medially; EPB and APL laterally. Floor = scaphoid , with the radial artery crossing it."}]},"anat1-surface-joints:e6":{"s":2,"u":["Shoulder: 3 degrees of freedom; lax capsule; anterior dislocations common.","Shoulder (scapulohumeral) : humeral head and glenoid cavity deepened by the glenoid labrum ; a very lax capsule reinforced in front by the coracohumeral and superior, middle and inferior glenohumeral ligaments ; three degrees of freedom : flexion (antepulsion, 180°) and extension (retropulsion, 50°), abduction (180°) and adduction, internal and external rotation, combined in circumduction.","Little bony interlocking and great mobility explain frequent dislocations, mostly anterior ; X-rays show bones and joint space but not capsule, ligaments or cartilage."],"dp":[{"h":"Clinical","t":"Shoulder dislocation is usually anterior (lax capsule, shallow glenoid): the rounded contour and the deltopectoral groove are lost ('squared-off' shoulder). Check the axillary nerve (regimental badge area)."}]},"anat1-surface-joints:e7":{"s":2,"u":["Glenohumeral ligaments + coracohumeral ligament reinforce the front.","Shoulder (scapulohumeral) : humeral head and glenoid cavity deepened by the glenoid labrum ; a very lax capsule reinforced in front by the coracohumeral and superior, middle and inferior glenohumeral ligaments ; three degrees of freedom : flexion (antepulsion, 180°) and extension (retropulsion, 50°), abduction (180°) and adduction, internal and external rotation, combined in circumduction."],"dp":[]},"anat1-surface-joints:e8":{"s":2,"u":["Elbow: humero-ulnar, humeroradial, proximal radio-ulnar; 1 degree (flexion-extension).","Elbow : three joints in one capsule: humero-ulnar (trochlea and trochlear notch), humeroradial (capitulum and radial head) and proximal radio-ulnar , reinforced by the medial and lateral collateral ligaments; one degree of freedom : flexion (about 130°) and extension; it also takes part in pronation-supination (about 180° in total) with the radio-ulnar joints.","Wrist (radiocarpal) : distal radius and the triangular fibrocartilage above the scaphoid, lunate and triquetrum ; two degrees of freedom : flexion and extension (about 90° each) and radial (about 15°) and ulnar (about 45°) deviation."],"dp":[{"h":"Note","t":"Degrees of freedom: shoulder 3 , elbow 1 (+ pronation/supination with radio-ulnar joints), wrist 2 (flexion-extension, radial and ulnar deviation; ulnar deviation is larger)."}]},"anat1-surface-joints:e9":{"s":2,"u":["Wrist: radius + TFCC with scaphoid, lunate, triquetrum; 2 degrees.","Wrist (radiocarpal) : distal radius and the triangular fibrocartilage above the scaphoid, lunate and triquetrum ; two degrees of freedom : flexion and extension (about 90° each) and radial (about 15°) and ulnar (about 45°) deviation."],"dp":[{"h":"Why tenderness in the snuffbox matters","t":"The scaphoid lies in the floor of the anatomical snuffbox. After a fall on the outstretched hand, pain when pressing there suggests a scaphoid fracture even if the first X-ray looks normal. Because the scaphoid's blood supply enters distally, a missed fracture can cut off its proximal part and lead to avascular necrosis, so the wrist is immobilised and imaged again. Source: the handout's anatomical snuffbox description."}]}},"meta":{"3if4dy":{"a":"recall","vg":"anat1-surface-joints:e1/recall/1"},"1oqvtfp":{"a":"recall","vg":"anat1-surface-joints:e1/recall/2"},"j6bxbz":{"a":"recall","vg":"anat1-surface-joints:e2/recall/1"},"xv00mj":{"a":"recall","vg":"anat1-surface-joints:e3/recall/1"},"168n4j4":{"a":"relationship","vg":"anat1-surface-joints:e4/relationship/1"},"1bh0twk":{"a":"recall","vg":"anat1-surface-joints:e5/recall/1"},"19rv1e1":{"a":"recall","vg":"anat1-surface-joints:e6/recall/1"},"txt7fh":{"a":"relationship","vg":"anat1-surface-joints:e6/relationship/1"},"ivrpwd":{"a":"recall","vg":"anat1-surface-joints:e7/recall/1"},"1yy22z4":{"a":"recall","vg":"anat1-surface-joints:e8/recall/1"},"1mvuo4j":{"a":"recall","vg":"anat1-surface-joints:e8/recall/2"},"e83cd9":{"a":"recall","vg":"anat1-surface-joints:e9/recall/1"},"12e2fkg":{"a":"recall","vg":"anat1-surface-joints:e9/recall/2"}},"explRev":"1b3c88b10171"};
